import com.yahoo.searchlib.rankingexpression.RankingExpression;
import com.yahoo.searchlib.rankingexpression.evaluation.Context;
import com.yahoo.searchlib.rankingexpression.evaluation.MapContext;
import com.yahoo.searchlib.rankingexpression.evaluation.TensorValue;
import com.yahoo.searchlib.rankingexpression.integration.tensorflow.importer.TensorConverter;
import com.yahoo.searchlib.rankingexpression.rule.CompositeNode;
import com.yahoo.searchlib.rankingexpression.rule.ExpressionNode;
import com.yahoo.searchlib.rankingexpression.rule.ReferenceNode;
import com.yahoo.tensor.Tensor;
import com.yahoo.tensor.TensorType;
import org.tensorflow.SavedModelBundle;
import org.tensorflow.Session;

import java.nio.FloatBuffer;
import java.util.List;

public class Verify {
    static final int d0Size = 1, d1Size = 784;

    public static void main(String[] args) {
        String dir = args[0];
        SavedModelBundle tf = SavedModelBundle.load(dir, "serve");
        TensorFlowModel model = new TensorFlowImporter().importModel(tf);

        TensorFlowModel.Signature sig = model.signatures().get("serving_default");
        System.out.println("skippedOutputs=" + sig.skippedOutputs());
        RankingExpression output = sig.outputExpression("y");
        System.out.println("NAME=" + output.getName());
        System.out.println("ROOT=" + output.getRoot().toString());

        // numeric comparison
        Tensor tfResult = tfExecute(tf, "X", output.getName());
        Context context = contextFrom(model);
        context.put("X", new TensorValue(placeholder()));
        for (String k : model.macros().keySet()) evaluateMacro(context, model, k);
        Tensor vespaResult = model.expressions().get(output.getName()).evaluate(context).asTensor();
        System.out.println("TF   =" + tfResult);
        System.out.println("VESPA=" + vespaResult);
        System.out.println("EQUAL=" + tfResult.equals(vespaResult));
    }

    static Tensor tfExecute(SavedModelBundle model, String in, String op) {
        Session.Runner runner = model.session().runner();
        FloatBuffer fb = FloatBuffer.allocate(d0Size * d1Size);
        for (int i = 0; i < d1Size; ++i) fb.put(i, (float)(i * 1.0 / d1Size));
        org.tensorflow.Tensor<?> ph = org.tensorflow.Tensor.create(new long[]{d0Size, d1Size}, fb);
        runner.feed(in, ph);
        List<org.tensorflow.Tensor<?>> results = runner.fetch(op).run();
        return TensorConverter.toVespaTensor(results.get(0));
    }

    static Context contextFrom(TensorFlowModel r) {
        MapContext c = new MapContext();
        r.largeConstants().forEach((n,t) -> c.put("constant(" + n + ")", new TensorValue(t)));
        r.smallConstants().forEach((n,t) -> c.put("constant(" + n + ")", new TensorValue(t)));
        return c;
    }

    static Tensor placeholder() {
        Tensor.Builder b = Tensor.Builder.of(new TensorType.Builder().indexed("d0", d0Size).indexed("d1", d1Size).build());
        for (int d0=0; d0<d0Size; d0++) for (int d1=0; d1<d1Size; d1++) b.cell(d1 * 1.0 / d1Size, d0, d1);
        return b.build();
    }

    static void evaluateMacro(Context c, TensorFlowModel m, String name) {
        if (!c.names().contains(name)) {
            RankingExpression e = m.macros().get(name);
            deps(c, m, e.getRoot());
            c.put(name, new TensorValue(e.evaluate(c).asTensor()));
        }
    }
    static void deps(Context c, TensorFlowModel m, ExpressionNode node) {
        if (node instanceof ReferenceNode) {
            String n = node.toString();
            if (m.macros().containsKey(n)) evaluateMacro(c, m, n);
        } else if (node instanceof CompositeNode) {
            for (ExpressionNode ch : ((CompositeNode)node).children()) deps(c, m, ch);
        }
    }
}
