+// Copyright 2018 Yahoo Holdings. Licensed under the terms of the Apache 2.0 license. See LICENSE in the project root.
+package com.yahoo.searchlib.rankingexpression.integration.tensorflow.importer.operations;
+
+import com.yahoo.searchlib.rankingexpression.integration.tensorflow.importer.DimensionRenamer;
+import com.yahoo.searchlib.rankingexpression.integration.tensorflow.importer.OrderedTensorType;
+import com.yahoo.tensor.TensorType;
+import com.yahoo.tensor.functions.Reduce;
+import com.yahoo.tensor.functions.TensorFunction;
+import org.tensorflow.framework.NodeDef;
+
+import java.util.ArrayList;
+import java.util.List;
+import java.util.Optional;
+import java.util.function.DoubleBinaryOperator;
+
+public class Join extends TensorFlowOperation {
+
+    private final DoubleBinaryOperator operator;
+
+    public Join(NodeDef node, List<TensorFlowOperation> inputs, int port, DoubleBinaryOperator operator) {
+        super(node, inputs, port);
+        this.operator = operator;
+    }
+
+    @Override
+    protected OrderedTensorType lazyGetType() {
+        if (!allInputTypesPresent(2)) {
+            return null;
+        }
+        // The result of a join with broadcasting has the rank of the largest input, and the size of
+        // each dimension is the largest of the two inputs.
+        OrderedTensorType a = largestInput().type().get();
+        OrderedTensorType b = smallestInput().type().get();
+        return a.type().rank() >= b.type().rank() ? a : b;
+    }
+
+    @Override
+    protected TensorFunction lazyGetFunction() {
+        if (!allInputTypesPresent(2)) {
+            return null;
+        }
+        Optional<TensorFunction> aFunction = largestInput().function();
+        Optional<TensorFunction> bFunction = smallestInput().function();
+        if (!aFunction.isPresent() || !bFunction.isPresent()) {
+            return null;
+        }
+
+        // The larger-ranked tensor is placed as the first argument to the join. When the tensors
+        // have a different number of dimensions we must handle broadcasting explicitly: dimensions
+        // of size 1 in one tensor which are of a larger size in the other are reduced away (using a
+        // sum, which does not change the value as the dimension only holds a single cell) so that the
+        // join broadcasts the single value against all cells of the corresponding dimension.
+        OrderedTensorType aType = largestInput().type().get();
+        OrderedTensorType bType = smallestInput().type().get();
+
+        List<String> aDimensionsToReduce = new ArrayList<>();
+        List<String> bDimensionsToReduce = new ArrayList<>();
+        int sizeDifference = aType.rank() - bType.rank();
+        for (int i = 0; i < bType.rank(); ++i) {
+            TensorType.Dimension bDim = bType.dimensions().get(i);
+            TensorType.Dimension aDim = aType.dimensions().get(i + sizeDifference);
+            long bSize = bDim.size().orElse(-1L);
+            long aSize = aDim.size().orElse(-1L);
+            if (bSize == 1L && aSize != 1L) {
+                bDimensionsToReduce.add(bDim.name());
+            }
+            if (aSize == 1L && bSize != 1L) {
+                aDimensionsToReduce.add(bDim.name());
+            }
+        }
+
+        TensorFunction aReducedFunction = aFunction.get();
+        if (aDimensionsToReduce.size() > 0) {
+            aReducedFunction = new Reduce(aFunction.get(), Reduce.Aggregator.sum, aDimensionsToReduce);
+        }
+        TensorFunction bReducedFunction = bFunction.get();
+        if (bDimensionsToReduce.size() > 0) {
+            bReducedFunction = new Reduce(bFunction.get(), Reduce.Aggregator.sum, bDimensionsToReduce);
+        }
+
+        return new com.yahoo.tensor.functions.Join(aReducedFunction, bReducedFunction, operator);
+    }
+
+    @Override
+    public void addDimensionNameConstraints(DimensionRenamer renamer) {
+        if (!allInputTypesPresent(2)) {
+            return;
+        }
+
+        // Well now we have potentially entered the wonderful world of "broadcasting"
+        // https://docs.scipy.org/doc/numpy/user/basics.broadcasting.html
+        // I'm not able to extract from that any unambiguous specification of which dimensions
+        // should be "stretched" when the tensor do not have the same number of dimensions.
+        // From trying this with TensorFlow it appears that the second tensor is matched to the
+        // "end" (highest numbered) dimensions of the first, but I'm not sure whether this is generally true.
+        // Anyway, we move the dimensions of b to the last dimensions of a (instead of by default, the first).
+
+        OrderedTensorType a = largestInput().type().get();
+        OrderedTensorType b = smallestInput().type().get();
+        int sizeDifference = a.rank() - b.rank();
+        for (int i = 0; i < b.rank(); ++i) {
+            String bDim = b.dimensions().get(i).name();
+            String aDim = a.dimensions().get(i + sizeDifference).name();
+            renamer.addConstraint(aDim, bDim, DimensionRenamer::equals, this);
+        }
+    }
+
+    private TensorFlowOperation largestInput() {
+        OrderedTensorType a = inputs.get(0).type().get();
+        OrderedTensorType b = inputs.get(1).type().get();
+        return a.rank() >= b.rank() ? inputs.get(0) : inputs.get(1);
+    }
+
+    private TensorFlowOperation smallestInput() {
+        OrderedTensorType a = inputs.get(0).type().get();
+        OrderedTensorType b = inputs.get(1).type().get();
+        return a.rank() < b.rank() ? inputs.get(0) : inputs.get(1);
+    }
+
+}
